77	export function validateAgentAccounts(value, source) {
78	    if (!Array.isArray(value)) throw new Error(`Invalid agent accounts in ${source}`);
79	    const accounts = value.map((account, index) => validateAgentAccount(account, `${source}[${index}]`));
