48	            if (settled) return;
49	            settled = true;
50	            if (exitCode === 0) {
51	                resolve({ stderr, stdout });
52	                return;
53	            }
54	            reject(new Error(`Codex update failed: ${processErrorMessage(stderr, stdout, exitCode)}`));
